            if out[13][c] == 6:
                out[13][c] = 1
        return out

    # Complete a partial horizontal stripe by marking its remaining background.
    for row in grid:
        colors = {v for v in row if v !=  (row[0] if row.count(row[0]) > len(row)//2 else -1)}
    # Find the dominant background color, then recolor the complement of any
    # non-background contiguous stripe occupying one side of a row.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        nonbg = [c for c, v in enumerate(row) if v != bg]
        if not nonbg:
            continue
        color = row[nonbg[0]]
        if any(row[c] != color for c in nonbg):
            continue
        lo, hi = min(nonbg), max(nonbg)
        if nonbg != list(range(lo, hi + 1)) or len(nonbg) * 2 != w:
            continue
        if lo == 0:
            for c in range(hi + 1, w):
